import XCTest

@testable import CodeConnect

/// **Starting a session from the phone, against the daemon's own bytes.**
///
/// `minor-28-wire.json` is what ccd emits for `list_projects` and
/// `start_session` (`fixtures/claude/minor-28-wire.json`, regenerated by ccd's
/// test and copied here byte for byte), so the shapes these tests read are the
/// shapes the computer writes.
@MainActor
final class SessionStartTests: XCTestCase {

    // MARK: Harness

    private func wire() throws -> [String: JSONValue] {
        let url = try XCTUnwrap(
            Bundle(for: type(of: self)).url(forResource: "minor-28-wire", withExtension: "json"))
        return try XCTUnwrap(
            try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
    }

    private func frame(_ key: String) throws -> ServerMessage {
        let value = try XCTUnwrap(try wire()[key], "no \(key) in minor-28-wire.json")
        return try JSONDecoder().decode(ServerMessage.self, from: Data(value.canonicalJSONString.utf8))
    }

    private final class Sent {
        var sent: [ClientMessage] = []

        var starts: [(requestID: String, path: String, agent: String, prompt: String?)] {
            sent.compactMap {
                guard case .startSession(let id, let path, let agent, let prompt, _) = $0 else { return nil }
                return (id, path, agent, prompt)
            }
        }

        var listings: Int {
            sent.filter { if case .listProjects = $0 { return true } else { return false } }.count
        }
    }

    private func capabilities(startsSessions: Bool) throws -> Capabilities {
        var advertised = try XCTUnwrap(try wire()["hello_ack_capabilities"]?.objectValue)
        if !startsSessions { advertised["start_session"] = nil }
        return try JSONDecoder().decode(
            Capabilities.self, from: Data(JSONValue.object(advertised).canonicalJSONString.utf8))
    }

    private func model(startsSessions: Bool = true) throws -> (AppModel, Sent) {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("start-\(UUID().uuidString)")
        addTeardownBlock { try? FileManager.default.removeItem(at: root) }
        let model = AppModel(
            cache: EventCache(root: root),
            codexSpentLedger: CodexSpentLedger(
                defaults: UserDefaults(suiteName: "cc.tests.\(UUID().uuidString)")!))
        model.connection.simulateConnectedForTesting()
        model.connection.simulateCapabilitiesForTesting(
            try capabilities(startsSessions: startsSessions), minor: 28)
        let wire = Sent()
        model.connection.sendStub = { message in
            MainActor.assumeIsolated { wire.sent.append(message) }
        }
        addTeardownBlock { @MainActor in model.scenePhaseChanged(to: .background) }
        return (model, wire)
    }

    /// Let the send tasks run.
    private func settle() async {
        for _ in 0..<5 { await Task.yield() }
    }

    private func project(_ model: AppModel) throws -> StartProject {
        model.connection.injectForTesting(try frame("projects"))
        return try XCTUnwrap(model.starter.projects?.first { $0.exists })
    }

    // MARK: The wire

    /// The phone's two requests encode to exactly what ccd parses.
    func testRequestsEncodeAsTheDaemonReadsThem() throws {
        let root = try wire()
        let encoder = JSONEncoder()
        let list = try JSONDecoder().decode(
            JSONValue.self, from: encoder.encode(ClientMessage.listProjects))
        XCTAssertEqual(list, root["list_projects_request"])

        let expected = try XCTUnwrap(root["start_session_request"]?.objectValue)
        let start = ClientMessage.startSession(
            requestID: try XCTUnwrap(expected["request_id"]?.stringValue),
            path: try XCTUnwrap(expected["path"]?.stringValue),
            agent: try XCTUnwrap(expected["agent"]?.stringValue),
            prompt: expected["prompt"]?.stringValue)
        XCTAssertEqual(
            try JSONDecoder().decode(JSONValue.self, from: encoder.encode(start)), .object(expected))
    }

    func testProjectsDecodeWithTheirAgents() throws {
        guard case .projects(let projects, let agents) = try frame("projects") else {
            return XCTFail("not a projects reply")
        }
        XCTAssertGreaterThanOrEqual(projects.count, 3)
        XCTAssertTrue(projects.contains { $0.gitBranch != nil })
        XCTAssertTrue(projects.contains { $0.gitBranch == nil })
        XCTAssertTrue(projects.contains { !$0.exists })
        XCTAssertTrue(projects.allSatisfy { $0.lastUsed != .distantPast })
        XCTAssertEqual(projects.map(\.lastUsed), projects.map(\.lastUsed).sorted(by: >), "most recent first")
        XCTAssertTrue(agents.contains { $0.available })
        let unavailable = try XCTUnwrap(agents.first { !$0.available })
        XCTAssertNotNil(unavailable.detail)
    }

    func testEachResultDecodesToItsOutcome() throws {
        guard case .startSessionResult(_, .started(let uid, _)) = try frame("start_started") else {
            return XCTFail("started")
        }
        XCTAssertFalse(uid.isEmpty)
        for (key, reason) in [
            ("start_failed_folder_missing", StartFailure.folderMissing),
            ("start_failed_agent_missing", .agentMissing),
            ("start_failed_launch_failed", .launchFailed),
        ] {
            guard case .startSessionResult(_, .failed(let decoded, let detail)) = try frame(key) else {
                return XCTFail(key)
            }
            XCTAssertEqual(decoded, reason, key)
            XCTAssertFalse(detail.isEmpty, key)
        }
    }

    /// The daemon's answer to a resent request id is its first answer, again.
    func testARepeatedRequestIsAnsweredTheSameWay() throws {
        let replies = try XCTUnwrap(try wire()["start_repeat"]?.arrayValue)
        XCTAssertEqual(replies.count, 2)
        let decoded = try replies.map {
            try JSONDecoder().decode(ServerMessage.self, from: Data($0.canonicalJSONString.utf8))
        }
        guard case .startSessionResult(let first, let a) = decoded[0],
            case .startSessionResult(let second, let b) = decoded[1]
        else { return XCTFail("not results") }
        XCTAssertEqual(first, second)
        XCTAssertEqual(a, b)
    }

    /// A reason this build has never heard of is still a start that did not
    /// happen, in the computer's words.
    func testAnUnknownReasonIsAFailureWithItsDetail() throws {
        let json = #"{"type":"start_session_result","request_id":"r9","result":{"status":"failed","reason":"quota_exceeded","detail":"no more sessions today"}}"#
        guard
            case .startSessionResult("r9", .failed(.launchFailed, "no more sessions today")) =
                try JSONDecoder().decode(ServerMessage.self, from: Data(json.utf8))
        else { return XCTFail("decoded otherwise") }
    }

    // MARK: The model

    func testAComputerWithoutTheCapabilityIsNeverAsked() async throws {
        let (model, sent) = try model(startsSessions: false)
        model.listProjects()
        await settle()
        XCTAssertEqual(sent.listings, 0)
    }

    func testProjectsAreAskedForAndKept() async throws {
        let (model, sent) = try model()
        model.listProjects()
        await settle()
        XCTAssertEqual(sent.listings, 1)
        model.connection.injectForTesting(try frame("projects"))
        guard case .projects(let projects, let agents) = try frame("projects") else { return XCTFail() }
        XCTAssertEqual(model.starter.projects, projects)
        XCTAssertEqual(model.starter.agents, agents)
    }

    func testAStartSendsTheListedPathAndItsOutcomeArrivesByRequestID() async throws {
        let (model, sent) = try model()
        let project = try project(model)
        let id = model.startSession(project, agent: .claude, prompt: "  fix the build  ")
        await settle()
        XCTAssertEqual(sent.starts.count, 1)
        XCTAssertEqual(sent.starts.first?.requestID, id)
        XCTAssertEqual(sent.starts.first?.path, project.path)
        XCTAssertEqual(sent.starts.first?.agent, "claude")
        XCTAssertEqual(sent.starts.first?.prompt, "fix the build")

        let started = try frame("start_started")
        guard case .startSessionResult(_, let outcome) = started else { return XCTFail() }
        model.connection.injectForTesting(.startSessionResult(requestID: id, outcome: outcome))
        XCTAssertEqual(model.starter.starts[id]?.outcome, outcome)
    }

    func testAnEmptyFirstMessageIsLeftOut() async throws {
        let (model, sent) = try model()
        _ = model.startSession(try project(model), agent: .claude, prompt: " \n ")
        await settle()
        XCTAssertNil(try XCTUnwrap(sent.starts.first).prompt)
    }

    /// The link drops before the answer: the next handshake sends the same
    /// start again under the same id, and an answered one is not sent again.
    func testAReconnectResendsTheUnansweredStartUnchanged() async throws {
        let (model, sent) = try model()
        let project = try project(model)
        let waiting = model.startSession(project, agent: .claude, prompt: "one")
        let answered = model.startSession(project, agent: .claude, prompt: "two")
        await settle()
        model.connection.injectForTesting(
            .startSessionResult(requestID: answered, outcome: .started(sessionUID: "01KANSWERED")))

        let ack = try XCTUnwrap(try wire()["hello_ack_capabilities"])
        let hello = """
            {"type":"hello_ack","protocol_version":\(Wire.protocolVersion),"protocol_minor":28,\
            "server_time":"2026-11-04T03:00:00.000Z","capabilities":\(ack.canonicalJSONString)}
            """
        model.connection.injectForTesting(try JSONDecoder().decode(ServerMessage.self, from: Data(hello.utf8)))
        await settle()

        XCTAssertEqual(sent.starts.map(\.requestID), [waiting, answered, waiting])
        XCTAssertEqual(sent.starts.last?.prompt, "one")
    }

    /// The daemon answers a repeated request id with its first outcome, and
    /// the phone keeps the first answer it got.
    func testTheFirstAnswerIsTheAnswer() async throws {
        let (model, _) = try model()
        let id = model.startSession(try project(model), agent: .claude, prompt: "")
        model.connection.injectForTesting(
            .startSessionResult(requestID: id, outcome: .started(sessionUID: "01KFIRST")))
        model.connection.injectForTesting(
            .startSessionResult(requestID: id, outcome: .failed(.launchFailed, detail: "late")))
        XCTAssertEqual(model.starter.starts[id]?.outcome, .started(sessionUID: "01KFIRST"))
    }

    func testAnAnswerForAnotherPhonesRequestIsIgnored() async throws {
        let (model, _) = try model()
        model.connection.injectForTesting(
            .startSessionResult(requestID: "not-ours", outcome: .started(sessionUID: "01KX")))
        XCTAssertTrue(model.starter.starts.isEmpty)
    }

    /// A folder is in the checkout at its path, else at its nearest enclosing
    /// folder; `/x/app-old` does not hold `/x/app`'s files.
    func testAFolderIsInTheCheckoutThatHoldsIt() {
        func checkout(_ path: String, _ branch: String) -> StartWorktree {
            StartWorktree(path: path, main: path == "/x/app", branch: branch, dirty: false, missing: false)
        }
        let git = StartGit(
            worktrees: [
                checkout("/x/app", "main"), checkout("/x/app-old", "old"),
                checkout("/x/app/.claude/worktrees/a", "worktree-a"),
            ],
            branches: [], branchesTruncated: false)
        XCTAssertEqual(git.checkout(at: "/x/app")?.branch, "main")
        XCTAssertEqual(git.checkout(at: "/x/app/web")?.branch, "main")
        XCTAssertEqual(git.checkout(at: "/x/app-old/web")?.branch, "old")
        XCTAssertEqual(git.checkout(at: "/x/app/.claude/worktrees/a/src")?.branch, "worktree-a")
        XCTAssertNil(git.checkout(at: "/x/ap"))
        XCTAssertEqual(git.others(than: "/x/app/web").map(\.branch), ["old", "worktree-a"])
    }

    /// Claude Code's worktree name rule, and the branch each agent makes.
    func testANewWorktreeNameFollowsClaudesRule() {
        for good in ["fix-login", "a/b", "v1.2_x", String(repeating: "a", count: 64)] {
            XCTAssertTrue(StartPlace.isValidName(good), good)
        }
        for bad in ["", "has space", "ünï", "..", "a/../b", "a//b", "/a", "a/", "semi;", String(repeating: "a", count: 65)] {
            XCTAssertFalse(StartPlace.isValidName(bad), bad)
        }
        XCTAssertEqual(StartPlace.newBranch("fix/login", for: .claude), "worktree-fix/login")
        XCTAssertEqual(StartPlace.newBranch("fix/login", for: .codex), "fix/login")
    }

    /// The last-used agent is offered only while it is installed.
    func testThePreferredAgentIsTheLastUsedOneWhileInstalled() {
        let project = StartProject(
            path: "/p", name: "p", lastUsed: Date(), lastAgent: .codex, gitBranch: nil, exists: true)
        XCTAssertEqual(project.preferredAgent(among: [.claude, .codex]), .codex)
        XCTAssertEqual(project.preferredAgent(among: [.claude]), .claude)
        XCTAssertNil(project.preferredAgent(among: []))
    }
}
